  package     org . unigram . docvalidator . validator . sentence ;   import   java . util . ArrayList ;  import   java . util . List ;  import   java . util . Set ;  import     org . unigram . docvalidator . store . Sentence ;  import     org . unigram . docvalidator . util . CharacterTable ;  import     org . unigram . docvalidator . util . ValidatorConfiguration ;  import     org . unigram . docvalidator . util . DVCharacter ;  import     org . unigram . docvalidator . util . DocumentValidatorException ;  import     org . unigram . docvalidator . util . ValidationError ;  import     org . unigram . docvalidator . validator . SentenceValidator ;   public class InvalidCharacterValidator  implements  SentenceValidator  {   public  List  < ValidationError > check  (  Sentence sentence )  {   List  < ValidationError >  errors =  new  ArrayList  < ValidationError >  ( ) ;   Set  < String >  names =  characterTable . getNames  ( ) ;  for ( String name : names )  {  ValidationError  error =  validateCharacter  ( sentence , name ) ;  if  (  error != null )  {   errors . add  ( error ) ; } }  return errors ; }   public boolean initialize  (  ValidatorConfiguration conf ,  CharacterTable characters )  throws DocumentValidatorException  {    this . characterTable = characters ;  return true ; }   private ValidationError validateCharacter  (  Sentence sentence ,  String name )  {  String  sentenceStr =  sentence . content ;  DVCharacter  character =  characterTable . getCharacter  ( name ) ;   List  < String >  invalidCharsList =  character . getInvalidChars  ( ) ;  for ( String invalidChar : invalidCharsList )  {  if  (  sentenceStr . contains  ( invalidChar ) )  {  return  new ValidationError  (   "Invalid symbol found: \"" + invalidChar + "\"" , sentence ) ; } }  return null ; }   private CharacterTable  characterTable ;   protected void setCharacterTable  (  CharacterTable characters )  {    this . characterTable = characters ; } }